// biowasm aligner bridge for the rusty-dot browser app.
//
// Message protocol (Shiny custom messages from Python):
//   'rd_mount_fasta'  {dataset_id, text}
//       Store a plain-FASTA payload under a stable id (the upload's content
//       digest).  Python sends each dataset once per session, so re-runs and
//       tool switches never re-copy multi-megabyte genomes across the
//       Pyodide/JS boundary again.
//   'rd_run_aligner'  {tool, args, query_id, target_id, request_id}
//       Run a tool against two previously mounted datasets.
//   'rd_cancel_aligner' {request_id}
//       Cancel the in-flight/queued run with that id: queued runs are
//       dropped before executing, and a best-effort attempt is made to
//       terminate the tool's WebWorker so the wasm computation actually
//       stops (falling back to ignore-the-result if the worker handle is
//       not reachable through Aioli's public surface).
//   'rd_extend_aligner' {request_id, ms}
//       Re-arm the run watchdog for that id, giving the tool another
//       `ms` milliseconds before the app is prompted again.
//
// Results return via
//   Shiny.setInputValue('aligner_result',
//       {request_id, tool, output, error, cancelled, stderr, cmd},
//       {priority: 'event'})
// On failure `output` is null and `error` carries a human-readable message.
// `stderr` (the tool's log) and `cmd` (the exact command line) are always
// included so the app can show a run log.
//
// A long run notifies rather than fails:
//   Shiny.setInputValue('aligner_timeout',
//       {request_id, tool, waited_ms, total_ms}, {priority: 'event'})
// The run keeps going; the app decides whether to extend the watchdog
// ('rd_extend_aligner') or cancel it ('rd_cancel_aligner').
//
// Aioli runs in its own WebWorker, so it never contends with the Pyodide
// runtime that executes the Shiny app itself.

(function () {
  'use strict';

  var AIOLI_URL = 'https://biowasm.com/cdn/v3/aioli/3.2.3/aioli.js';

  // tool key -> {module: biowasm CDN module spec, program: CLI program
  // name, outputFile: file to read back instead of stdout (or null)}
  var TOOLS = {
    minimap2: { module: 'minimap2/2.22', program: 'minimap2', outputFile: null },
    nucmer: {
      // Object spec: Aioli's 3-part string form is tool/PROGRAM/version,
      // so the object form is used to keep the fields unambiguous.
      module: { tool: 'mummer4', version: '4.0.0rc1', program: 'nucmer' },
      program: 'nucmer',
      outputFile: 'out.delta',
    },
  };

  // Python owns these names (core/align.py TARGET_FILENAME / QUERY_FILENAME);
  // build_tool_args embeds them in the CLI args, and we mount under the same
  // names so the args resolve inside the Aioli filesystem.
  var QUERY_FILENAME = 'query.fa';
  var TARGET_FILENAME = 'target.fa';

  var aioliScriptPromise = null; // loads aioli.js once
  var cliPromises = {}; // tool key -> Promise<Aioli instance>
  var runQueue = Promise.resolve(); // serialises runs (shared out.delta etc.)
  var datasets = {}; // dataset_id -> FASTA text (session-lived)
  // Which datasets are mounted on each tool's CLI instance; torn down with it.
  var mountedOn = {}; // tool key -> 'queryId|targetId'
  var cancelledIds = {}; // request_id -> true (queued runs drop themselves)
  var cancelResolvers = {}; // request_id -> resolve fn unblocking the queue
  var currentRun = null; // {requestId, tool} while a tool is executing

  // A hung init (bad CDN asset, unreachable biowasm) must reject rather
  // than block the run queue forever -- there is no useful "wait longer"
  // story for a fetch that is never going to arrive.
  var INIT_TIMEOUT_MS = 180000;

  // Runs are different: real assemblies can legitimately keep a wasm
  // aligner busy for many minutes (minimap2 -c especially), and the
  // WebWorker keeps computing regardless of what this side does with the
  // promise.  So the per-tool budget is a *watchdog*: when it expires the
  // app is told, the run continues, and the app either extends the budget
  // or cancels for real.
  var RUN_TIMEOUT_MS = {
    minimap2: 300000,
    nucmer: 600000,
  };

  // request_id -> {timer, tool, startedAt, waited}
  var watchdogs = {};

  function armWatchdog(requestId, tool, ms) {
    if (!requestId) return; // pre-warm runs are not watched
    var w = watchdogs[requestId];
    if (!w) {
      w = watchdogs[requestId] = { timer: null, tool: tool, startedAt: Date.now() };
    }
    clearTimeout(w.timer);
    w.timer = setTimeout(function () {
      // Notify only.  The entry is kept so 'rd_extend_aligner' can re-arm
      // it; the run itself is untouched and still racing to finish.
      w.timer = null;
      if (!window.Shiny || !window.Shiny.setInputValue) return;
      window.Shiny.setInputValue(
        'aligner_timeout',
        {
          request_id: requestId,
          tool: w.tool,
          waited_ms: ms,
          total_ms: Date.now() - w.startedAt,
        },
        { priority: 'event' }
      );
    }, ms);
  }

  function extendWatchdog(msg) {
    if (!msg || !msg.request_id) return;
    var w = watchdogs[msg.request_id];
    if (!w) return; // already finished or cancelled
    armWatchdog(msg.request_id, w.tool, msg.ms || RUN_TIMEOUT_MS[w.tool] || 300000);
  }

  function clearWatchdog(requestId) {
    var w = watchdogs[requestId];
    if (!w) return;
    clearTimeout(w.timer);
    delete watchdogs[requestId];
  }

  function withTimeout(promise, what, ms) {
    return Promise.race([
      promise,
      new Promise(function (resolve, reject) {
        setTimeout(function () {
          reject(new Error(what + ' timed out after ' + ms / 1000 + 's'));
        }, ms);
      }),
    ]);
  }

  function loadAioliScript() {
    if (window.Aioli) return Promise.resolve();
    if (!aioliScriptPromise) {
      aioliScriptPromise = new Promise(function (resolve, reject) {
        var s = document.createElement('script');
        s.src = AIOLI_URL;
        s.onload = function () {
          resolve();
        };
        s.onerror = function () {
          aioliScriptPromise = null; // allow retry on the next run
          reject(
            new Error(
              'Could not load Aioli from the biowasm CDN (' +
                AIOLI_URL +
                ') — check your network connection.'
            )
          );
        };
        document.head.appendChild(s);
      });
    }
    return aioliScriptPromise;
  }

  function getCli(tool) {
    if (!cliPromises[tool]) {
      mountedOn[tool] = null; // fresh instance, nothing mounted yet
      cliPromises[tool] = withTimeout(
        loadAioliScript().then(function () {
          // printInterleaved:false keeps stdout separate from stderr —
          // minimap2 writes its PAF output to stdout but also logs
          // progress to stderr, and the default interleaved string is
          // unparseable.
          return new window.Aioli([TOOLS[tool].module], {
            printInterleaved: false,
          });
        }),
        'Initialising ' + tool + ' from biowasm',
        INIT_TIMEOUT_MS
      ).catch(function (err) {
          cliPromises[tool] = null; // allow retry on the next run
          throw new Error(
            'Could not initialise ' + tool + ' from biowasm: ' + errText(err)
          );
        });
    }
    return cliPromises[tool];
  }

  // Best-effort worker termination.  Aioli does not officially expose its
  // WebWorker; probe the common handles and fall back to just abandoning
  // the instance (its result is ignored and the next run re-initialises).
  function teardownTool(tool) {
    var pending = cliPromises[tool];
    cliPromises[tool] = null;
    mountedOn[tool] = null;
    if (!pending) return;
    pending.then(
      function (cli) {
        try {
          var worker =
            (cli && cli.worker) ||
            (cli && cli._worker) ||
            (cli && cli.config && cli.config.worker);
          if (worker && typeof worker.terminate === 'function') {
            worker.terminate();
            return;
          }
        } catch (err) {
          // fall through to the console note below
        }
        // eslint-disable-next-line no-console
        console.warn(
          'rusty-dot: could not reach the ' +
            tool +
            ' worker to terminate it; its result will be ignored but the ' +
            'computation may continue until it finishes or times out.'
        );
      },
      function () {
        // init already failed; nothing to terminate
      }
    );
  }

  function errText(err) {
    if (err === undefined || err === null) return 'unknown error';
    if (err instanceof Error) return err.message;
    return String(err);
  }

  async function runAligner(msg) {
    var spec = TOOLS[msg.tool];
    if (!spec) throw new Error('Unknown aligner tool: ' + msg.tool);
    var queryText = datasets[msg.query_id];
    var targetText = datasets[msg.target_id];
    if (typeof queryText !== 'string' || typeof targetText !== 'string') {
      throw new Error(
        'Assembly data not found in the browser session — please press ' +
          'Run again.'
      );
    }
    if (!window.Aioli) sendProgress(msg.request_id, msg.tool, 'loading-aioli');
    if (!cliPromises[msg.tool]) {
      sendProgress(msg.request_id, msg.tool, 'initialising-tool');
    }
    var CLI = await getCli(msg.tool);
    if (spec.outputFile) {
      // Remove any output left by a previous run on this cached CLI
      // instance: if the tool fails, a stale file must not be read back
      // and reported as this run's result.
      try {
        await CLI.fs.unlink(spec.outputFile);
      } catch (err) {
        // Not present (first run) — fine.
      }
    }
    var mountKey = msg.query_id + '|' + msg.target_id;
    if (mountedOn[msg.tool] !== mountKey) {
      sendProgress(msg.request_id, msg.tool, 'mounting-data');
      await CLI.mount([
        { name: QUERY_FILENAME, data: queryText },
        { name: TARGET_FILENAME, data: targetText },
      ]);
      mountedOn[msg.tool] = mountKey;
    }
    var cmd = [spec.program].concat(msg.args || []).join(' ');
    sendProgress(msg.request_id, msg.tool, 'aligning');
    var res;
    currentRun = { requestId: msg.request_id, tool: msg.tool };
    armWatchdog(msg.request_id, msg.tool, RUN_TIMEOUT_MS[msg.tool] || 300000);
    try {
      // Deliberately not raced against a timer: the run ends only by
      // completing, erroring, or being cancelled.  Rejecting here would
      // report a failure while the worker kept burning CPU on a run that
      // was about to succeed.
      res = await CLI.exec(cmd);
    } finally {
      clearWatchdog(msg.request_id);
      currentRun = null;
    }
    sendProgress(msg.request_id, msg.tool, 'reading-output');
    var stdout = res && typeof res === 'object' ? res.stdout : res;
    var stderr = res && typeof res === 'object' ? res.stderr : '';
    if (spec.outputFile) {
      var fileText;
      try {
        fileText = await CLI.fs.readFile(spec.outputFile, { encoding: 'utf8' });
      } catch (err) {
        throw new Error(
          msg.tool +
            ' did not produce ' +
            spec.outputFile +
            ' (tool output: ' +
            String(stderr || stdout).slice(0, 500) +
            ')'
        );
      }
      return { output: fileText, stderr: String(stderr || ''), cmd: cmd };
    }
    return {
      output: typeof stdout === 'string' ? stdout : String(stdout),
      stderr: String(stderr || ''),
      cmd: cmd,
    };
  }

  function sendResult(payload) {
    window.Shiny.setInputValue('aligner_result', payload, { priority: 'event' });
  }

  // Stage updates for the in-flight run ('loading-aioli',
  // 'initialising-tool', 'mounting-data', 'aligning', 'reading-output').
  // Pre-warm runs have no request id and stay silent.
  function sendProgress(requestId, tool, stage) {
    if (!requestId || !window.Shiny || !window.Shiny.setInputValue) return;
    window.Shiny.setInputValue(
      'aligner_progress',
      { request_id: requestId, tool: tool, stage: stage },
      { priority: 'event' }
    );
  }

  function handleMount(msg) {
    if (msg && msg.dataset_id && typeof msg.text === 'string') {
      datasets[msg.dataset_id] = msg.text;
    }
  }

  function handleCancel(msg) {
    if (!msg || !msg.request_id) return;
    cancelledIds[msg.request_id] = true;
    clearWatchdog(msg.request_id);
    if (currentRun && currentRun.requestId === msg.request_id) {
      // The tool is executing right now: kill its worker so the CPU work
      // actually stops (best-effort; see teardownTool).
      teardownTool(currentRun.tool);
      currentRun = null;
    }
    // Unblock the queue immediately — a terminated worker's exec promise
    // never settles, and the next run must not wait behind it.
    var release = cancelResolvers[msg.request_id];
    if (release) release({ cancelled: true });
  }

  function handleMessage(msg) {
    // Serialise runs: concurrent nucmer runs would race on out.delta, and
    // biowasm downloads are friendlier one at a time.
    runQueue = runQueue
      .then(function () {
        if (cancelledIds[msg.request_id]) {
          // Cancelled while queued: drop before doing any work, so a
          // superseded run cannot burn CPU behind the one the user wants.
          delete cancelledIds[msg.request_id];
          return { cancelled: true };
        }
        var cancelPromise = new Promise(function (resolve) {
          cancelResolvers[msg.request_id] = resolve;
        });
        var runPromise = runAligner(msg);
        // The losing promise of the race may reject later (e.g. the
        // timeout of a terminated run); swallow it so it never surfaces
        // as an unhandled rejection.
        runPromise.catch(function () {});
        return Promise.race([runPromise, cancelPromise]).finally(function () {
          delete cancelResolvers[msg.request_id];
        });
      })
      .then(
        function (res) {
          if (res && res.cancelled) {
            sendResult({
              request_id: msg.request_id,
              tool: msg.tool,
              output: null,
              error: null,
              cancelled: true,
              stderr: '',
              cmd: '',
            });
            return;
          }
          sendResult({
            request_id: msg.request_id,
            tool: msg.tool,
            output: res.output,
            error: null,
            cancelled: false,
            stderr: res.stderr,
            cmd: res.cmd,
          });
        },
        function (err) {
          var wasCancelled = !!cancelledIds[msg.request_id];
          delete cancelledIds[msg.request_id];
          sendResult({
            request_id: msg.request_id,
            tool: msg.tool,
            output: null,
            error: wasCancelled ? null : errText(err),
            cancelled: wasCancelled,
            stderr: '',
            cmd: '',
          });
        }
      );
  }

  function register() {
    // Inside the shinylive iframe `Shiny` is the in-frame global; it may
    // not exist yet when this script runs, so poll briefly.
    if (window.Shiny && window.Shiny.addCustomMessageHandler) {
      window.Shiny.addCustomMessageHandler('rd_mount_fasta', handleMount);
      window.Shiny.addCustomMessageHandler('rd_run_aligner', handleMessage);
      window.Shiny.addCustomMessageHandler('rd_cancel_aligner', handleCancel);
      window.Shiny.addCustomMessageHandler('rd_extend_aligner', extendWatchdog);
    } else {
      setTimeout(register, 100);
    }
  }

  // Pre-warm: start downloading a biowasm tool as soon as the user selects
  // it in the method menu, so the (one-time, ~seconds) CDN fetch overlaps
  // with choosing files and options instead of delaying the first Run.
  // getCli() caches the instance, so Run reuses whatever this started.
  document.addEventListener('change', function (ev) {
    var el = ev.target;
    if (!el || el.id !== 'method') return;
    if (TOOLS[el.value]) {
      getCli(el.value).catch(function () {
        // Ignore here: cliPromises resets itself on failure, and the real
        // run reports CDN errors to the user properly.
      });
    }
  });

  register();
})();

/* rusty-dot browser app styling.
 *
 * Theming: every colour goes through the custom-property layer below, so
 * light and dark mode stay in lockstep — dark mode overrides only the
 * variables. Motion uses the shared --rd-transition timing; larger state
 * changes (busy, recalculating) get their own eased transitions.
 */

:root {
  /* Palette — teal accent to match the docs site. */
  --rd-accent: #14847e;
  --rd-accent-soft: rgba(20, 132, 126, 0.12);
  --rd-fg: #22303c;
  --rd-muted: #4a5a6a;
  --rd-faint: #6c757d;
  --rd-surface: #f2f6fa;
  --rd-surface-strong: #eef4fb;
  --rd-on-surface-strong: #1f3a5f;
  --rd-border: rgba(128, 128, 128, 0.25);
  --rd-border-soft: #d5dee8;
  --rd-error-bg: #fdecea;
  --rd-error-fg: #7a1c13;
  --rd-frame-bg: #ffffff;

  /* Identity: translucent sidebar over a faint dot-grid page backdrop
     (the dotplot motif), display face for the wordmark and headings. */
  --rd-sidebar-bg: rgba(242, 246, 250, 0.72);
  --rd-page-dot: rgba(34, 48, 60, 0.1);
  --rd-font-display: 'Space Grotesk', var(--bs-body-font-family, sans-serif);

  /* Shape & motion. */
  --rd-radius: 8px;
  --rd-radius-sm: 5px;
  --rd-transition: 160ms ease;
  --rd-font-mono: var(--bs-font-monospace, monospace);
}

/* Dark palette.  The header toggle (ui.input_dark_mode) stamps
   data-bs-theme on <html>; before the first toggle it mirrors the system
   preference, so the media query is only a fallback that an explicit
   'light' choice must beat. */
@media (prefers-color-scheme: dark) {
  :root:not([data-bs-theme='light']) {
    --rd-accent: #2fb7b0;
    --rd-accent-soft: rgba(47, 183, 176, 0.16);
    --rd-fg: #d5dee7;
    --rd-muted: #aabdd0;
    --rd-faint: #8fa1b3;
    --rd-surface: #1c2733;
    --rd-surface-strong: #1d2b3d;
    --rd-on-surface-strong: #cfe1f5;
    --rd-border: rgba(160, 175, 190, 0.28);
    --rd-border-soft: #33404f;
    --rd-error-bg: #3d1d1d;
    --rd-error-fg: #f5cfcf;
    --rd-sidebar-bg: rgba(28, 39, 51, 0.72);
    --rd-page-dot: rgba(213, 222, 231, 0.09);
    /* The embedded report document is always light-themed; a light
       backdrop stops it flashing against a dark app while loading. */
    --rd-frame-bg: #f5f5f5;
  }
}

:root[data-bs-theme='dark'] {
  --rd-accent: #2fb7b0;
  --rd-accent-soft: rgba(47, 183, 176, 0.16);
  --rd-fg: #d5dee7;
  --rd-muted: #aabdd0;
  --rd-faint: #8fa1b3;
  --rd-surface: #1c2733;
  --rd-surface-strong: #1d2b3d;
  --rd-on-surface-strong: #cfe1f5;
  --rd-border: rgba(160, 175, 190, 0.28);
  --rd-border-soft: #33404f;
  --rd-error-bg: #3d1d1d;
  --rd-error-fg: #f5cfcf;
  --rd-sidebar-bg: rgba(28, 39, 51, 0.72);
  --rd-page-dot: rgba(213, 222, 231, 0.09);
  --rd-frame-bg: #f5f5f5;
}

/* --- branding --------------------------------------------------------- */

/* The dotplot motif: a faint dot grid behind the whole page. The
   translucent sidebar (below) floats over it. */
body {
  background-color: var(--bs-body-bg, #fff);
  background-image: radial-gradient(var(--rd-page-dot) 1px, transparent 1.4px);
  background-size: 22px 22px;
}

/* Page header: the title is a flex row — wordmark, tagline, and the
   task-status readout pushed to the right end. */
.rd-header-flex {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
  width: 100%;
  min-width: 0;
}

.navbar-brand,
.bslib-page-title {
  width: 100%;
}

/* The wordmark's middot is the brand: the one dot of the dotplot,
   set in the accent colour. */
.rd-wordmark {
  font-family: var(--rd-font-display);
  font-weight: 700;
  font-size: 1.3rem;
  letter-spacing: -0.02em;
  color: var(--rd-fg);
  white-space: nowrap;
}

.rd-wordmark-dot {
  color: var(--rd-accent);
}

.rd-wordmark-sub {
  font-size: 0.72rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--rd-muted);
  white-space: nowrap;
}

.bslib-page-title::after,
.navbar-brand::after {
  content: '';
  display: block;
  height: 3px;
  width: 3.5rem;
  margin-top: 2px;
  border-radius: 2px;
  background: linear-gradient(
    90deg,
    var(--rd-accent),
    var(--rd-accent-soft)
  );
}

/* Manual dark-mode toggle at the far right of the header. */
.rd-theme-toggle {
  flex: 0 0 auto;
  align-self: center;
  color: var(--rd-muted);
}

.rd-theme-toggle .form-check,
.rd-theme-toggle bslib-input-dark-mode {
  margin: 0;
}

/* Active-task readout at the right end of the header, fed by
   www/task-status.js from the (hidden) ui.Progress messages. */
.rd-task-status {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-size: 0.78rem;
  font-weight: 400;
  color: var(--rd-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  opacity: 0;
  transition: opacity var(--rd-transition);
}

.rd-task-status:not(:empty) {
  opacity: 1;
}

.rd-task-status:not(:empty)::before {
  content: '';
  flex: none;
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 50%;
  border: 2px solid var(--rd-accent-soft);
  border-top-color: var(--rd-accent);
  animation: rd-spin 0.9s linear infinite;
}

/* The ui.Progress popup card duplicates the header readout and the busy
   pill; task-status.js mirrors its text, so the card itself stays hidden.
   Ordinary ui.notification_show toasts have no progress node and remain
   visible. */
.shiny-notification:has(.shiny-progress-notification),
.shiny-progress-notification {
  display: none;
}

/* --- base blocks ------------------------------------------------------ */

.rd-status {
  padding: 0.75rem 1rem;
  margin-bottom: 0.75rem;
  border-radius: var(--rd-radius);
  background: var(--rd-surface-strong);
  color: var(--rd-on-surface-strong);
  font-size: 0.95rem;
  line-height: 1.45;
  transition: background-color var(--rd-transition), color var(--rd-transition);
}

.rd-status-error {
  background: var(--rd-error-bg);
  color: var(--rd-error-fg);
}

.sidebar .btn {
  width: 100%;
  margin-bottom: 0.35rem;
  transition:
    background-color var(--rd-transition),
    border-color var(--rd-transition),
    box-shadow var(--rd-transition),
    transform var(--rd-transition);
}

.sidebar .btn:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}

.sidebar .btn:active:not(:disabled) {
  transform: translateY(0);
}

.sidebar .btn-primary {
  background: var(--rd-accent);
  border-color: var(--rd-accent);
}

/* Translucent sidebar floating over the dot-grid backdrop. bslib paints
   the panel through its own --_sidebar-bg custom property; override both
   that and the background so the rule survives bslib version drift. */
.bslib-sidebar-layout {
  --_sidebar-bg: var(--rd-sidebar-bg);
}

.bslib-sidebar-layout > .sidebar {
  background-color: var(--rd-sidebar-bg);
  backdrop-filter: blur(10px) saturate(1.1);
  -webkit-backdrop-filter: blur(10px) saturate(1.1);
  border-right: 1px solid var(--rd-border);
}

/* Sidebar sections: subtle separation and tighter headings. */
.sidebar h5 {
  font-family: var(--rd-font-display);
  margin-top: 0.5rem;
  margin-bottom: 0.5rem;
  font-weight: 600;
  padding-bottom: 0.25rem;
  border-bottom: 1px solid var(--rd-border);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  opacity: 0.85;
}

/* Info icon in input labels; the setting's explanation appears in a
   tooltip on hover (see _lbl in app.py). */
.rd-info {
  color: var(--rd-faint);
  font-size: 0.85em;
  cursor: help;
}

.rd-info:hover {
  color: var(--rd-accent);
}

.sidebar .form-control,
.sidebar .form-select {
  transition: border-color var(--rd-transition), box-shadow var(--rd-transition);
}

.sidebar .form-control:focus,
.sidebar .form-select:focus {
  border-color: var(--rd-accent);
  box-shadow: 0 0 0 0.15rem var(--rd-accent-soft);
}

/* --- plot area -------------------------------------------------------- */

/* Drill-down tabs: quiet labels, accent underline on the active one. */
.rd-plot-area .nav-tabs .nav-link {
  font-family: var(--rd-font-display);
  font-weight: 500;
  font-size: 0.9rem;
  color: var(--rd-muted);
}

.rd-plot-area .nav-tabs .nav-link:hover {
  color: var(--rd-fg);
}

.rd-plot-area .nav-tabs .nav-link.active {
  color: var(--rd-fg);
  background: transparent;
  box-shadow: inset 0 -2px 0 var(--rd-accent);
}

.rd-plot-area {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  min-height: 0;
}

.rd-plot-toolbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.rd-back-btn {
  white-space: nowrap;
}

.rd-focus-label {
  font-weight: 600;
  font-family: var(--rd-font-mono);
  font-size: 0.9rem;
  color: var(--rd-fg);
}

/* Fullscreen toggle at the left end of the plot toolbar.  The icon pair
   swaps on html.rd-fullscreen (toggled by www/fullscreen.js). */
.rd-fs-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.3rem;
  border: 1px solid var(--rd-border);
  border-radius: var(--rd-radius);
  background: var(--rd-surface);
  color: var(--rd-muted);
  cursor: pointer;
  line-height: 0;
  transition: color var(--rd-transition), border-color var(--rd-transition);
}

.rd-fs-btn:hover {
  color: var(--rd-accent);
  border-color: var(--rd-accent);
}

.rd-fs-btn .rd-fs-collapse {
  display: none;
}

html.rd-fullscreen .rd-fs-btn .rd-fs-expand {
  display: none;
}

html.rd-fullscreen .rd-fs-btn .rd-fs-collapse {
  display: inline;
}

/* Compact 'how to navigate' hint below the interactive report. */
.rd-nav-hint {
  font-size: 0.78rem;
  line-height: 1.4;
  color: var(--rd-muted);
  background: var(--rd-surface);
  border: 1px solid var(--rd-border);
  border-radius: var(--rd-radius);
  padding: 0.3rem 0.6rem;
  transition: background-color var(--rd-transition), color var(--rd-transition);
}

.rd-nav-hint b {
  color: var(--rd-fg);
  font-weight: 600;
}

.rd-report-frame {
  width: 100%;
  height: 76vh;
  /* An inline replaced element leaves its wrapper measuring 0 tall, so the
     frame escapes every ancestor box that is not a flex container. */
  display: block;
  border: 1px solid var(--rd-border);
  border-radius: var(--rd-radius);
  background: var(--rd-frame-bg);
}

/* Fullscreen: the plot area becomes a fixed overlay covering the viewport;
   the frame drops its fixed height and fills the remaining column. */
html.rd-fullscreen .rd-plot-area {
  position: fixed;
  inset: 0;
  z-index: 1055;
  margin: 0;
  padding: 0.75rem;
  background: var(--bs-body-bg, #fff);
  overflow: auto;
}

html.rd-fullscreen .rd-plot-area .rd-report-frame {
  height: auto;
  flex: 1 1 auto;
  min-height: 0;
}

/* Stretch the wrapper chain (shiny output div, tab panes) so the frame's
   flex:1 actually reaches the viewport height. */
html.rd-fullscreen .rd-plot-area #report_frame {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 0;
}

html.rd-fullscreen .rd-plot-area .shiny-plot-output {
  flex: 1 1 auto;
  height: auto !important;
  min-height: 0;
}

html.rd-fullscreen body {
  overflow: hidden;
}

/* Fullscreen is the plot and its toolbar, nothing else: navigation
   hints, the memory readout and the drill-down tab strip all disappear
   (fullscreen.js activates the Plot tab on entry so the hidden strip can
   never strand the user on the Annotations pane).  The back-to-overview
   button stays: it swaps the view while fullscreen persists, since the
   state lives as a class on <html>. */
html.rd-fullscreen .rd-nav-hint,
html.rd-fullscreen .rd-mem-fixed,
html.rd-fullscreen .rd-plot-area .nav-tabs {
  display: none !important;
}

/* The drill-down wraps the report in Bootstrap tab panes, which navset_tab
   leaves as plain block boxes.  Give the active pane the same flex column
   the overview uses, so the frame is measured the same way in both views --
   otherwise .rd-plot-area computes shorter than the frame it contains, and
   the aligner log (the next sibling in the page body, with no z-index on
   either side) is laid out over the overflow and paints on top of it. */
.rd-plot-area .tab-content {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.rd-plot-area .tab-content > .tab-pane.active {
  display: flex;
  flex-direction: column;
  gap: 0.5rem; /* matches .rd-plot-area */
  min-height: 0;
}

/* In fullscreen the tab panes must also grow, so the frame's flex:1 above
   reaches the viewport height. */
html.rd-fullscreen .rd-plot-area .tab-content,
html.rd-fullscreen .rd-plot-area .tab-content > .tab-pane.active {
  flex: 1 1 auto;
}

/* Loading states: dim outputs while Shiny recomputes them. */
.recalculating,
.rd-plot-area .recalculating {
  opacity: 0.45;
  transition: opacity 250ms ease 250ms;
}

@keyframes rd-spin {
  to {
    transform: rotate(360deg);
  }
}

/* --- downloads -------------------------------------------------------- */

/* Disabled download placeholders (no result generated yet). */
.rd-dl-disabled {
  width: 100%;
  margin-bottom: 0.35rem;
  opacity: 0.5;
  cursor: not-allowed;
  border: 1px solid var(--rd-border-soft);
}

.rd-dl-note {
  font-size: 0.8rem;
  color: var(--rd-faint);
  margin-bottom: 0.5rem;
}

/* Hidden helper outputs (e.g. #result_kind drives conditional panels). */
.rd-hidden {
  display: none;
}

/* --- aligner run log -------------------------------------------------- */

.rd-log-accordion {
  margin: 0.75rem 0;
}

.rd-log {
  font-family: var(--rd-font-mono);
  font-size: 0.78rem;
  background: var(--rd-surface);
  border: 1px solid var(--rd-border-soft);
  border-radius: var(--rd-radius-sm);
  padding: 0.5rem 0.7rem;
  max-height: 16rem;
  overflow: auto;
  white-space: pre-wrap;
  word-break: break-word;
  color: var(--rd-fg);
}

/* --- GFF annotation controls ------------------------------------------ */

.rd-gff-section {
  margin: 0.4rem 0 0.6rem;
}

.rd-gff-section h6 {
  margin: 0.3rem 0;
  font-size: 0.8rem;
  color: var(--rd-muted);
}

/* Sidebar Apply for the feature-type toggles; its state is driven by
   ui.update_action_button, never by a re-render. */
.rd-gff-section .rd-gff-apply {
  margin-top: 0.45rem;
}

.rd-gff-type-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.rd-gff-type-row .form-group,
.rd-gff-type-row .checkbox {
  margin-bottom: 0.15rem;
}

/* Q / T badges: which upload(s) a shared feature type came from. */
.rd-gff-type-row .rd-gff-role {
  margin-left: auto;
  padding: 0 0.28rem;
  border: 1px solid var(--rd-border-soft);
  border-radius: 3px;
  font-size: 0.62rem;
  line-height: 1.25;
  color: var(--rd-muted);
}

.rd-color-input {
  width: 2rem;
  height: 1.4rem;
  padding: 0;
  border: 1px solid var(--rd-border-soft);
  border-radius: 3px;
  background: none;
  cursor: pointer;
  transition: box-shadow var(--rd-transition);
}

.rd-color-input:hover {
  box-shadow: 0 0 0 0.15rem var(--rd-accent-soft);
}

/* --- memory readout --------------------------------------------------- */

/* Fixed note at the bottom-right of the page (the busy pill stacks just
   above it while computing).  Hidden while the readout text is empty —
   e.g. native runs, or before the Pyodide heap is queryable. */
.rd-mem-fixed {
  position: fixed;
  right: 1rem;
  bottom: 1rem;
  z-index: 1500;
  padding: 0.25rem 0.7rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-family: var(--rd-font-mono);
  color: var(--rd-faint);
  background: var(--rd-surface);
  border: 1px solid var(--rd-border);
  pointer-events: none;
}

.rd-mem-fixed:has(.shiny-text-output:empty) {
  display: none;
}

/* --- drill-down annotations table -------------------------------------- */

.rd-ft-panel {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  padding: 0.5rem 0.2rem 0;
  /* Shiny's output wrappers are display:contents, so this is a flex item of
     the tab pane directly: let it shrink with the pane instead of pushing
     the table out past it. */
  flex: 1 1 auto;
  min-height: 0;
}

.rd-ft-caption {
  font-size: 0.82rem;
  color: var(--rd-muted);
}

.rd-ft-tools {
  display: flex;
  gap: 0.4rem;
  align-items: center;
  flex-wrap: wrap;
}

.rd-ft-tools input[type='search'] {
  flex: 1 1 16rem;
  min-width: 10rem;
  padding: 0.22rem 0.45rem;
  border: 1px solid var(--rd-border-soft);
  border-radius: 4px;
  background: var(--rd-surface);
  color: var(--rd-fg);
  font-size: 0.82rem;
}

.rd-ft-tools button {
  padding: 0.22rem 0.6rem;
  border: 1px solid var(--rd-border-soft);
  border-radius: 4px;
  background: none;
  color: var(--rd-fg);
  font-size: 0.78rem;
  cursor: pointer;
}

.rd-ft-tools button:hover {
  border-color: var(--rd-accent);
}

/* Per-column filter builder: a column picker, the text box, and the
   chips showing which filters are active. */
.rd-ft-filters {
  display: flex;
  gap: 0.4rem;
  align-items: center;
  flex: 1 1 22rem;
  min-width: 14rem;
}

.rd-ft-filters select {
  padding: 0.22rem 0.3rem;
  border: 1px solid var(--rd-border-soft);
  border-radius: 4px;
  background: var(--rd-surface);
  color: var(--rd-fg);
  font-size: 0.78rem;
}

.rd-ft-chips {
  display: flex;
  gap: 0.35rem;
  flex-wrap: wrap;
}

.rd-ft-chips:empty {
  display: none;
}

.rd-ft-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.1rem 0.3rem 0.1rem 0.5rem;
  border: 1px solid var(--rd-border-soft);
  border-radius: 999px;
  background: var(--rd-accent-soft);
  font-size: 0.75rem;
  color: var(--rd-fg);
}

.rd-ft-chip button {
  border: none;
  background: none;
  padding: 0 0.15rem;
  font-size: 0.85rem;
  line-height: 1;
  color: var(--rd-muted);
  cursor: pointer;
}

.rd-ft-chip button:hover {
  color: var(--rd-accent);
}

/* Selected rows, banded on the Plot tab. */
#rd-feature-table tbody tr.rd-row-selected {
  background: var(--rd-accent-soft);
  box-shadow: inset 3px 0 0 var(--rd-accent);
}

.rd-ft-hint {
  font-size: 0.75rem;
  color: var(--rd-muted);
}

/* The table scrolls inside its own box so the page never scrolls sideways,
   and shrinks to whatever height the pane leaves it (62vh is only a cap). */
.rd-ft-scroll {
  flex: 1 1 auto;
  min-height: 0;
  max-height: 62vh;
  overflow: auto;
  border: 1px solid var(--rd-border-soft);
  border-radius: 4px;
}

#rd-feature-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.78rem;
  font-variant-numeric: tabular-nums;
}

#rd-feature-table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 0.3rem 0.45rem;
  text-align: left;
  white-space: nowrap;
  background: var(--rd-surface);
  border-bottom: 1px solid var(--rd-border-soft);
  color: var(--rd-muted);
  font-weight: 600;
}

#rd-feature-table td {
  padding: 0.18rem 0.45rem;
  border-bottom: 1px solid var(--rd-border-soft);
  white-space: nowrap;
}

#rd-feature-table tbody tr:hover {
  background: var(--rd-accent-soft);
}

#rd-feature-table .rd-ft-num {
  text-align: right;
}

#rd-feature-table .rd-ft-attrs {
  max-width: 24rem;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--rd-muted);
}

#rd-feature-table .rd-color-input {
  width: 1.6rem;
  height: 1.1rem;
}

/* Apply-changes bar above the drill-down annotations table. */
.rd-ft-apply {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.5rem 0.2rem 0;
  flex-wrap: wrap;
}

.rd-ft-apply .rd-ft-apply-note {
  font-size: 0.78rem;
  color: var(--rd-muted);
}

/* Sortable annotation-table headers. */
#rd-feature-table thead th[data-sort] {
  cursor: pointer;
  user-select: none;
  padding-right: 1rem;
  position: sticky;
}

#rd-feature-table thead th[data-sort]:hover {
  color: var(--rd-fg);
}

#rd-feature-table thead th[data-sort]:focus-visible {
  outline: 2px solid var(--rd-accent);
  outline-offset: -2px;
}

/* Direction marker, drawn in the padding reserved above so the header
   text never shifts when the sort changes. */
#rd-feature-table thead th.rd-sort-asc::after,
#rd-feature-table thead th.rd-sort-desc::after {
  position: absolute;
  right: 0.3rem;
  color: var(--rd-accent);
}

#rd-feature-table thead th.rd-sort-asc::after {
  content: '▲';
}

#rd-feature-table thead th.rd-sort-desc::after {
  content: '▼';
}

/* rusty-dot app <-> embedded report bridge (W2).
 *
 * The interactive dotplot report is embedded in a sandboxed srcdoc iframe.
 * Two message flows cross that boundary:
 *
 * child -> parent
 *   'rd-panel-dblclick' {row, col}  — forwarded to Shiny as the
 *       'panel_dblclick' input so the app swaps to the single-pair view.
 *   'rd-report-ready'               — the report finished wiring; reply with
 *       the current display options (the iframe element is replaced on every
 *       re-render, so state must be re-sent each time).
 *   'rd-match-select' {row, col, layer, idx, qs, qe, ts, te, strand} — a
 *       clicked match wants its sequence preview (aligned when a CIGAR
 *       exists, plain slices otherwise); forwarded to Shiny as the
 *       'match_select' input.
 *   'rd-copy-request' {row, col, layer, idx, qs, qe, ts, te, strand,
 *       side} — a copy button wants one full match sequence ('query' or
 *       'target'); forwarded to Shiny as the 'copy_request' input.
 *
 * parent -> child
 *   'rd-display-opts' {dot_size, min_length} — display-only options applied
 *       client-side inside the report (CSS stroke width + per-segment
 *       hiding), so changing them never re-renders matplotlib in Pyodide.
 *       Values arrive from the server via the 'rd_display_opts' custom
 *       message. The child has an opaque origin (sandbox without
 *       allow-same-origin), so targetOrigin must be '*'.
 *   'rd-seq-response' {row, col, layer, idx, text?, aligned?, copy?,
 *       error?} — the sequence preview (or an error code) for a prior
 *       'rd-match-select'; arrives from the server via the 'rd_match_seq'
 *       custom message.
 *   'rd-copy-response' {row, col, layer, idx, side, seq?, error?} — one
 *       full match sequence for a prior 'rd-copy-request'; arrives from
 *       the server via the 'rd_copy_seq' custom message.
 *   'rd-fullscreen' {on} — the app entered/left plot fullscreen
 *       (fullscreen.js announces it via the 'rd-fs-change' CustomEvent);
 *       the report scales its figure to the viewport while on.
 *   'rd-restore-selection' {matches, feature} — re-apply the selection a
 *       previous iframe announced ('rd-match-selection' /
 *       'rd-feature-selection', below), so selections survive
 *       overview <-> drill-down swaps.
 *
 * child -> parent (selection bookkeeping)
 *   'rd-match-selection' {pairs, matches} — the current match selection in
 *       view-independent terms; entries for pairs the report shows replace
 *       the stored ones, selections on other pairs are kept.
 *   'rd-feature-selection' {feature|null} — the selected annotation/track
 *       feature, or null when cleared.
 *   'rd-selection-state' {any} / 'rd-esc' — consumed by fullscreen.js for
 *       Escape ordering (clear first, exit second).
 */
(function () {
  'use strict';

  var lastOpts = { dot_size: 0.5, min_length: 0 };
  // Features the annotations table currently has selected, held so a
  // re-rendered iframe gets them again (feature-table.js announces them
  // through the 'rd-ft-selection' CustomEvent).
  var lastHighlights = [];
  // Whether the app is in fullscreen (fullscreen.js announces changes via
  // the 'rd-fs-change' CustomEvent); the report scales its figure to the
  // viewport while set, and a re-rendered iframe must be told again.
  var lastFullscreen = false;
  // Match/feature selection in view-independent terms (display names +
  // data coordinates), announced by the report on every change and
  // restored into the fresh iframe after an overview <-> drill-down swap.
  var lastMatchSel = [];
  var lastFeatureSel = null;

  function pairKey(q, t) {
    return q + '�' + t;
  }

  function reportFrame() {
    return document.querySelector('iframe.rd-report-frame');
  }

  function pushHighlightsToReport() {
    var frame = reportFrame();
    if (frame && frame.contentWindow) {
      frame.contentWindow.postMessage(
        { type: 'rd-highlight-features', features: lastHighlights },
        '*'
      );
    }
  }

  document.addEventListener('rd-ft-selection', function (ev) {
    var features = ev && ev.detail && ev.detail.features;
    lastHighlights = Array.isArray(features) ? features : [];
    pushHighlightsToReport();
  });

  function pushFullscreenToReport() {
    var frame = reportFrame();
    if (frame && frame.contentWindow) {
      frame.contentWindow.postMessage(
        { type: 'rd-fullscreen', on: lastFullscreen },
        '*'
      );
    }
  }

  document.addEventListener('rd-fs-change', function (ev) {
    lastFullscreen = !!(ev && ev.detail && ev.detail.on);
    pushFullscreenToReport();
  });

  function pushOptsToReport() {
    var frame = reportFrame();
    if (frame && frame.contentWindow) {
      frame.contentWindow.postMessage(
        {
          type: 'rd-display-opts',
          dot_size: lastOpts.dot_size,
          min_length: lastOpts.min_length,
        },
        '*'
      );
    }
  }

  window.addEventListener('message', function (ev) {
    var msg = ev && ev.data;
    if (!msg) {
      return;
    }
    if (msg.type === 'rd-report-ready') {
      // Only trust the ping if it came from the current report iframe.
      var frame = reportFrame();
      if (frame && ev.source === frame.contentWindow) {
        pushOptsToReport();
        if (lastHighlights.length) pushHighlightsToReport();
        if (lastFullscreen) pushFullscreenToReport();
        if (lastMatchSel.length || lastFeatureSel) {
          frame.contentWindow.postMessage(
            {
              type: 'rd-restore-selection',
              matches: lastMatchSel,
              feature: lastFeatureSel,
            },
            '*'
          );
        }
      }
      return;
    }
    if (msg.type === 'rd-match-selection') {
      var selFrame = reportFrame();
      if (!selFrame || ev.source !== selFrame.contentWindow) return;
      // Replace the stored selection only for the pairs this report shows:
      // a drill-down update must not drop selections made in the overview
      // on pairs it does not display.
      var shown = {};
      (Array.isArray(msg.pairs) ? msg.pairs : []).forEach(function (p) {
        if (Array.isArray(p) && p.length === 2) shown[pairKey(p[0], p[1])] = true;
      });
      var kept = lastMatchSel.filter(function (m) {
        return !shown[pairKey(m.q, m.t)];
      });
      var fresh = (Array.isArray(msg.matches) ? msg.matches : []).filter(
        function (m) {
          return (
            m &&
            typeof m.q === 'string' &&
            typeof m.t === 'string' &&
            typeof m.layer === 'string' &&
            [m.qs, m.qe, m.ts, m.te].every(Number.isFinite)
          );
        }
      );
      lastMatchSel = kept.concat(fresh);
      return;
    }
    if (msg.type === 'rd-feature-selection') {
      var featFrame = reportFrame();
      if (!featFrame || ev.source !== featFrame.contentWindow) return;
      lastFeatureSel =
        msg.feature && typeof msg.feature === 'object' ? msg.feature : null;
      return;
    }
    if (msg.type === 'rd-match-select' || msg.type === 'rd-copy-request') {
      var frame2 = reportFrame();
      if (!frame2 || ev.source !== frame2.contentWindow) {
        return;
      }
      var mrow = Number(msg.row);
      var mcol = Number(msg.col);
      var midx = Number(msg.idx);
      if (
        !Number.isInteger(mrow) || mrow < 0 ||
        !Number.isInteger(mcol) || mcol < 0 ||
        !Number.isInteger(midx) || midx < 0 ||
        typeof msg.layer !== 'string'
      ) {
        return;
      }
      var payload = { row: mrow, col: mcol, layer: msg.layer, idx: midx };
      ['qs', 'qe', 'ts', 'te'].forEach(function (k) {
        var v = Number(msg[k]);
        if (Number.isFinite(v) && v >= 0) {
          payload[k] = v;
        }
      });
      if (msg.strand === '+' || msg.strand === '-') {
        payload.strand = msg.strand;
      }
      var inputName = 'match_select';
      if (msg.type === 'rd-copy-request') {
        if (msg.side !== 'query' && msg.side !== 'target') {
          return;
        }
        payload.side = msg.side;
        inputName = 'copy_request';
      }
      if (window.Shiny && typeof window.Shiny.setInputValue === 'function') {
        window.Shiny.setInputValue(inputName, payload, {
          priority: 'event',
        });
      }
      return;
    }
    if (msg.type === 'rd-bands') {
      // Which features the report is currently highlighting, so a saved
      // figure can carry the same bands.  Coordinates, not pixels: the
      // export is redrawn server-side rather than screenshotted.
      if (window.Shiny && typeof window.Shiny.setInputValue === 'function') {
        window.Shiny.setInputValue(
          'track_bands',
          { bands: Array.isArray(msg.bands) ? msg.bands : [] },
          { priority: 'event' }
        );
      }
      return;
    }
    if (msg.type !== 'rd-panel-dblclick') {
      return;
    }
    var row = Number(msg.row);
    var col = Number(msg.col);
    if (!Number.isInteger(row) || !Number.isInteger(col) || row < 0 || col < 0) {
      return;
    }
    if (window.Shiny && typeof window.Shiny.setInputValue === 'function') {
      window.Shiny.setInputValue(
        'panel_dblclick',
        { row: row, col: col },
        { priority: 'event' }
      );
    }
  });

  function register() {
    if (window.Shiny && window.Shiny.addCustomMessageHandler) {
      window.Shiny.addCustomMessageHandler('rd_display_opts', function (opts) {
        if (!opts) {
          return;
        }
        if (typeof opts.dot_size === 'number' && opts.dot_size > 0) {
          lastOpts.dot_size = opts.dot_size;
        }
        if (typeof opts.min_length === 'number' && opts.min_length >= 0) {
          lastOpts.min_length = opts.min_length;
        }
        pushOptsToReport();
      });
      window.Shiny.addCustomMessageHandler('rd_match_seq', function (msg) {
        var frame = reportFrame();
        if (frame && frame.contentWindow && msg) {
          frame.contentWindow.postMessage(
            Object.assign({ type: 'rd-seq-response' }, msg),
            '*'
          );
        }
      });
      window.Shiny.addCustomMessageHandler('rd_copy_seq', function (msg) {
        var frame = reportFrame();
        if (frame && frame.contentWindow && msg) {
          frame.contentWindow.postMessage(
            Object.assign({ type: 'rd-copy-response' }, msg),
            '*'
          );
        }
      });
      // Reset file inputs the server has cleared.  Shiny's FileInputBinding
      // has a no-op setValue, so this cannot be done with an input message:
      // without it the old filename stays on screen, and re-picking the same
      // file fires no change event, so it would never reload.
      window.Shiny.addCustomMessageHandler(
        'rd_clear_file_inputs',
        function (msg) {
          var ids = (msg && msg.ids) || [];
          ids.forEach(function (id) {
            var el = document.getElementById(id);
            if (!el) return;
            el.value = '';
            var group = el.closest('.input-group');
            if (group) {
              var text = group.querySelector('input[type="text"]');
              if (text) text.value = '';
            }
            var wrap = el.closest('.form-group') || (group && group.parentNode);
            var bar = wrap && wrap.querySelector('.progress-bar');
            if (bar) {
              bar.style.width = '0%';
              bar.textContent = '';
            }
            var progress = wrap && wrap.querySelector('.progress');
            if (progress) progress.style.visibility = 'hidden';
          });
        }
      );
    } else {
      setTimeout(register, 100);
    }
  }

  register();
})();

// Minimal Shiny input binding for native <input type="color"> pickers.
//
// Shiny for Python ships no colour input; this binding turns any
// <input type="color" class="rd-color-input" id="..."> into a regular
// Shiny input whose value is the '#rrggbb' hex string.  Change events are
// debounced by the 250 ms rate policy so dragging inside the OS colour
// dialog doesn't re-render the plot per intermediate colour.

(function () {
  'use strict';

  function register() {
    if (!window.Shiny || !window.Shiny.InputBinding) {
      setTimeout(register, 100);
      return;
    }
    var binding = new window.Shiny.InputBinding();
    Object.assign(binding, {
      find: function (scope) {
        return scope.querySelectorAll ?
          scope.querySelectorAll('input.rd-color-input') :
          [];
      },
      getId: function (el) {
        return el.id;
      },
      getValue: function (el) {
        return el.value;
      },
      setValue: function (el, value) {
        el.value = value;
      },
      subscribe: function (el, callback) {
        el.addEventListener('input', el._rdColorHandler = function () {
          callback(true); // true -> apply the debounce rate policy
        });
        el.addEventListener('change', el._rdColorChange = function () {
          callback(false);
        });
      },
      unsubscribe: function (el) {
        el.removeEventListener('input', el._rdColorHandler);
        el.removeEventListener('change', el._rdColorChange);
      },
      getRatePolicy: function () {
        return { policy: 'debounce', delay: 250 };
      },
    });
    window.Shiny.inputBindings.register(binding, 'rusty-dot.colorInput');
  }

  register();
})();

// The drill-down Annotations table, built and driven client-side.
//
// The server ships a static shell (header, tools, empty tbody) and posts
// the row data through the 'rd_feature_rows' custom message; this file
// builds the body.  Rendering ~600 rows per sequence as raw HTML through
// a @render.ui made the Plot <-> Annotations tab switch stall, since
// Shiny re-inserted and re-scanned the whole blob on every re-show.
//
// The rows carry raw <input> controls rather than one Shiny input per
// feature: ~1200 bound inputs (each with its own binding and message
// round-trip) visibly freezes Pyodide.  Instead a single listener on the
// container posts *deltas*:
//
//   Shiny.setInputValue('feature_table_change',
//       {kind: 'vis'|'color', uid, value}, {priority: 'event'})
//   Shiny.setInputValue('feature_table_change',
//       {kind: 'bulk'|'color', uids: [...], value}, {priority: 'event'})
//
// Filtering, sorting and row selection are purely client-side and never
// reach the server; selected rows are announced to bridge.js through a
// 'rd-ft-selection' CustomEvent so the report can band them.

(function () {
  'use strict';

  var TABLE_ID = 'rd-feature-table';

  function send(payload) {
    if (!window.Shiny || !window.Shiny.setInputValue) return;
    window.Shiny.setInputValue('feature_table_change', payload, {
      priority: 'event',
    });
  }

  function table() {
    return document.getElementById(TABLE_ID);
  }

  function visibleRows() {
    var t = table();
    if (!t) return [];
    return Array.prototype.filter.call(t.tBodies[0].rows, function (row) {
      return row.style.display !== 'none';
    });
  }

  function uidsOf(rows) {
    return rows.map(function (r) {
      return r.getAttribute('data-uid');
    });
  }

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function fmt(n) {
    // Same thousands separators the server used to format with; the
    // numeric sort strips them back out.
    return Number(n).toLocaleString('en-US');
  }

  // --- building the table body from the pushed payload --------------------

  var lastPayload = null;

  function rowHtml(r, idx) {
    return (
      '<tr data-uid="' + esc(r.uid) + '" data-idx="' + idx + '"' +
      ' data-type="' + esc(r.type) + '" data-source="' + esc(r.source) + '"' +
      ' data-role="' + esc(r.role) + '" data-contig="' + esc(r.contig) + '"' +
      // 0-based start for the report payload; the cell shows 1-based.
      ' data-start="' + (Number(r.start) - 1) + '"' +
      ' data-end="' + Number(r.end) + '"' +
      ' data-strand="' + esc(r.strand) + '">' +
      '<td><input type="checkbox" data-uid="' + esc(r.uid) +
      '" data-kind="vis"' + (r.visible ? ' checked' : '') + '></td>' +
      '<td><input type="color" data-uid="' + esc(r.uid) +
      '" data-kind="color" value="' + esc(r.color) +
      '" data-type-color="' + esc(r.type_color) +
      '" class="rd-color-input"></td>' +
      '<td class="rd-ft-role">' + esc(r.role) + '</td>' +
      '<td class="rd-ft-contig">' + esc(r.contig) + '</td>' +
      '<td class="rd-ft-type">' + esc(r.type) + '</td>' +
      '<td class="rd-ft-name">' + esc(r.name) + '</td>' +
      '<td class="rd-ft-num">' + fmt(r.start) + '</td>' +
      '<td class="rd-ft-num">' + fmt(r.end) + '</td>' +
      '<td class="rd-ft-num">' + fmt(r.length) + '</td>' +
      '<td>' + esc(r.strand) + '</td>' +
      '<td class="rd-ft-src">' + esc(r.source) + '</td>' +
      '<td class="rd-ft-attrs" title="' + esc(r.attrs) + '">' +
      esc(r.attrs) + '</td>' +
      '</tr>'
    );
  }

  function fillColumnSelect(t) {
    var sel = document.getElementById('rd-ft-filter-col');
    if (!sel) return;
    var opts = '<option value="-1">Any column</option>';
    Array.prototype.forEach.call(t.tHead.rows[0].cells, function (th, i) {
      var kind = th.getAttribute('data-sort');
      // Checkbox and swatch columns hold no text to filter on.
      if (kind === 'check' || kind === 'color') return;
      opts += '<option value="' + i + '">' + esc(th.textContent) + '</option>';
    });
    sel.innerHTML = opts;
  }

  function resetSortIndicators(t) {
    sortCol = null;
    sortDir = 0;
    Array.prototype.forEach.call(t.tHead.rows[0].cells, function (cell) {
      cell.setAttribute('aria-sort', 'none');
      cell.classList.remove('rd-sort-asc', 'rd-sort-desc');
    });
  }

  function populate() {
    var t = table();
    if (!t || !lastPayload) return;
    var rows = lastPayload.rows || [];
    t.tBodies[0].innerHTML = rows.map(rowHtml).join('');
    resetSortIndicators(t);
    fillColumnSelect(t);
    // Announce the emptied selection so bridge.js drops any held
    // highlights -- new rows mean the old uids no longer apply.
    clearSelection(true);
    applyFilters();
    var caption = document.querySelector('.rd-ft-caption');
    if (caption && lastPayload.pair) {
      caption.innerHTML =
        '<b>' + rows.length + '</b> feature(s) on <b>' +
        esc(lastPayload.pair[0]) + '</b> and <b>' +
        esc(lastPayload.pair[1]) + '</b>. ' +
        'Coordinates are 1-based inclusive, as in the source file. ' +
        'A feature loaded from two files (e.g. GenBank + GFF) lists once ' +
        'per source.';
    }
  }

  // The shell and the row payload race: the message can arrive before the
  // shell's DOM exists, and the shell can be re-inserted (plot_area
  // re-renders) without a fresh message.  The observer catches both: any
  // insertion that leaves an empty tbody next to a held payload gets
  // filled.
  new MutationObserver(function () {
    var t = table();
    if (t && lastPayload && t.tBodies[0].rows.length === 0) populate();
  }).observe(document.documentElement, { childList: true, subtree: true });

  function register() {
    if (window.Shiny && window.Shiny.addCustomMessageHandler) {
      window.Shiny.addCustomMessageHandler('rd_feature_rows', function (msg) {
        if (!msg || !Array.isArray(msg.rows)) return;
        lastPayload = msg;
        if (table()) populate();
      });
    } else {
      setTimeout(register, 100);
    }
  }

  register();

  // --- per-row toggles and colour pickers ---------------------------------
  document.addEventListener('change', function (ev) {
    var el = ev.target;
    if (!el || !el.getAttribute) return;
    var uid = el.getAttribute('data-uid');
    var kind = el.getAttribute('data-kind');
    if (!uid || !kind) return;
    if (!el.closest || !el.closest('#' + TABLE_ID)) return;
    if (kind === 'vis') {
      send({ kind: 'vis', uid: uid, value: el.checked });
    } else if (kind === 'color') {
      send({ kind: 'color', uid: uid, value: el.value });
    }
  });

  // --- bulk buttons -------------------------------------------------------
  // Bulk actions apply to the rows currently *visible* under the filter, so
  // "Hide all" after filtering to one type does what it looks like it does.
  document.addEventListener('click', function (ev) {
    var btn = ev.target;
    if (!btn || !btn.getAttribute) return;
    var action = btn.getAttribute('data-bulk');
    if (!action) return;
    var rows = visibleRows();
    if (!rows.length) return;
    var uids = uidsOf(rows);
    if (action === 'show' || action === 'hide') {
      var show = action === 'show';
      rows.forEach(function (r) {
        var box = r.querySelector('input[data-kind="vis"]');
        if (box) box.checked = show;
      });
      send({ kind: 'bulk', uids: uids, value: show });
    } else if (action === 'reset') {
      // Empty value means "drop the override and fall back to the type
      // colour" -- otherwise there is no way back from a per-feature pick.
      // Repaint the swatches here too: edits are held until Apply, so the
      // table does not re-render on this and the server cannot put them
      // back.  Each input carries its type colour for exactly this.
      rows.forEach(function (r) {
        var picker = r.querySelector('input[data-kind="color"]');
        if (picker && picker.dataset.typeColor) {
          picker.value = picker.dataset.typeColor;
        }
      });
      send({ kind: 'color', uids: uids, value: '' });
    }
  });

  // --- column sorting -----------------------------------------------------
  // Sorting is done here rather than on the server for the same reason the
  // table posts deltas: re-rendering hundreds of rows is the cost this
  // design exists to avoid, and it would throw away edits the user has not
  // applied yet.  Moving the existing <tr> elements keeps every checkbox,
  // swatch and data attribute attached to its row.

  var sortCol = null; // th currently sorted by
  var sortDir = 0; // 1 asc, -1 desc, 0 file order

  function cellKey(row, index, kind) {
    var cell = row.cells[index];
    if (!cell) return '';
    if (kind === 'check') {
      var box = cell.querySelector('input[type="checkbox"]');
      return box && box.checked ? 1 : 0;
    }
    if (kind === 'color') {
      var picker = cell.querySelector('input[type="color"]');
      return picker ? picker.value.toLowerCase() : '';
    }
    if (kind === 'num') {
      // Cells are formatted with thousands separators.
      var n = parseFloat(cell.textContent.replace(/,/g, ''));
      return isNaN(n) ? -Infinity : n;
    }
    return cell.textContent.trim().toLowerCase();
  }

  function applySort(th) {
    var t = table();
    if (!t) return;
    var index = th.cellIndex;
    var kind = th.getAttribute('data-sort') || 'text';

    if (sortCol === th) {
      // asc -> desc -> back to the order the file gave us.
      sortDir = sortDir === 1 ? -1 : sortDir === -1 ? 0 : 1;
    } else {
      sortCol = th;
      sortDir = 1;
    }

    var rows = Array.prototype.slice.call(t.tBodies[0].rows);
    if (sortDir === 0) {
      sortCol = null;
      rows.sort(function (a, b) {
        return (+a.getAttribute('data-idx')) - (+b.getAttribute('data-idx'));
      });
    } else {
      rows.sort(function (a, b) {
        var ka = cellKey(a, index, kind);
        var kb = cellKey(b, index, kind);
        if (ka < kb) return -sortDir;
        if (ka > kb) return sortDir;
        // Ties keep file order, so repeated sorts are stable and the
        // result never depends on the previous sort.
        return (+a.getAttribute('data-idx')) - (+b.getAttribute('data-idx'));
      });
    }

    var frag = document.createDocumentFragment();
    rows.forEach(function (r) {
      frag.appendChild(r);
    });
    t.tBodies[0].appendChild(frag);

    Array.prototype.forEach.call(t.tHead.rows[0].cells, function (cell) {
      var active = cell === th && sortDir !== 0;
      cell.setAttribute(
        'aria-sort',
        active ? (sortDir === 1 ? 'ascending' : 'descending') : 'none'
      );
      cell.classList.toggle('rd-sort-asc', active && sortDir === 1);
      cell.classList.toggle('rd-sort-desc', active && sortDir === -1);
    });
  }

  document.addEventListener('click', function (ev) {
    var th = ev.target.closest ? ev.target.closest('th[data-sort]') : null;
    if (!th || !th.closest('#' + TABLE_ID)) return;
    applySort(th);
  });

  document.addEventListener('keydown', function (ev) {
    if (ev.key !== 'Enter' && ev.key !== ' ') return;
    var th = ev.target.closest ? ev.target.closest('th[data-sort]') : null;
    if (!th || !th.closest('#' + TABLE_ID)) return;
    ev.preventDefault();
    applySort(th);
  });

  // --- per-column filters -------------------------------------------------
  // Several filters can be active at once, ANDed together; each targets one
  // column (or the whole row).  They take effect on "Apply filters" -- a
  // long table repainting on every keystroke is the lag the button avoids.

  var filters = []; // {colIndex, label, needle}

  function renderChips() {
    var box = document.getElementById('rd-ft-chips');
    if (!box) return;
    box.innerHTML = filters
      .map(function (f, i) {
        return (
          '<span class="rd-ft-chip">' + esc(f.label) + ': “' +
          esc(f.needle) + '”' +
          '<button type="button" data-chip="' + i +
          '" title="Remove this filter" aria-label="Remove filter">' +
          '&times;</button></span>'
        );
      })
      .join('');
  }

  function applyFilters() {
    var t = table();
    if (!t) return;
    Array.prototype.forEach.call(t.tBodies[0].rows, function (row) {
      var shown = filters.every(function (f) {
        var hay;
        if (f.colIndex < 0) {
          hay =
            row.getAttribute('data-type') + ' ' +
            row.getAttribute('data-source') + ' ' +
            row.textContent;
        } else {
          var cell = row.cells[f.colIndex];
          hay = cell ? cell.textContent : '';
        }
        return hay.toLowerCase().indexOf(f.needle) !== -1;
      });
      row.style.display = shown ? '' : 'none';
    });
  }

  function addFilterFromInput() {
    var input = document.getElementById('rd-ft-filter');
    var sel = document.getElementById('rd-ft-filter-col');
    if (!input || !sel) return;
    var needle = input.value.trim().toLowerCase();
    if (!needle) return;
    filters.push({
      colIndex: Number(sel.value),
      label: sel.options[sel.selectedIndex].textContent,
      needle: needle,
    });
    input.value = '';
    renderChips();
  }

  document.addEventListener('click', function (ev) {
    var el = ev.target;
    if (!el || !el.getAttribute) return;
    if (el.id === 'rd-ft-filter-add') {
      addFilterFromInput();
      return;
    }
    if (el.id === 'rd-ft-filter-apply') {
      // Text still sitting in the box counts too, so typing one filter
      // and pressing Apply works without an explicit Add.
      addFilterFromInput();
      applyFilters();
      return;
    }
    var chip = el.getAttribute('data-chip');
    if (chip !== null && el.closest('#rd-ft-chips')) {
      filters.splice(Number(chip), 1);
      renderChips();
      applyFilters(); // removing a filter is itself the action
    }
  });

  document.addEventListener('keydown', function (ev) {
    if (ev.key !== 'Enter') return;
    var el = ev.target;
    if (!el || el.id !== 'rd-ft-filter') return;
    ev.preventDefault();
    addFilterFromInput();
    applyFilters();
  });

  // --- row selection ------------------------------------------------------
  // Click selects a row, ⌘/Ctrl-click toggles it into a multi-selection.
  // bridge.js relays the selection into the report iframe, which bands the
  // matching features on the plot.

  var selectedUids = new Set();

  function announceSelection() {
    var t = table();
    var features = [];
    if (t) {
      Array.prototype.forEach.call(t.tBodies[0].rows, function (row) {
        if (!selectedUids.has(row.getAttribute('data-uid'))) return;
        features.push({
          uid: row.getAttribute('data-uid'),
          role: row.getAttribute('data-role'),
          seqname: row.getAttribute('data-contig'),
          start: Number(row.getAttribute('data-start')),
          end: Number(row.getAttribute('data-end')),
          type: row.getAttribute('data-type'),
          strand: row.getAttribute('data-strand'),
        });
      });
    }
    document.dispatchEvent(
      new CustomEvent('rd-ft-selection', { detail: { features: features } })
    );
  }

  function clearSelection(announce) {
    selectedUids.clear();
    var t = table();
    if (t) {
      Array.prototype.forEach.call(
        t.querySelectorAll('tr.rd-row-selected'),
        function (row) {
          row.classList.remove('rd-row-selected');
        }
      );
    }
    if (announce !== false) announceSelection();
  }

  document.addEventListener('click', function (ev) {
    var el = ev.target;
    if (!el || !el.closest) return;
    // The row's own controls keep their meaning; only bare-cell clicks
    // select.
    if (el.closest('input, button, select, a, label')) return;
    var row = el.closest('#' + TABLE_ID + ' tbody tr');
    if (!row) return;
    var uid = row.getAttribute('data-uid');
    if (!uid) return;
    if (ev.metaKey || ev.ctrlKey) {
      if (selectedUids.has(uid)) {
        selectedUids.delete(uid);
        row.classList.remove('rd-row-selected');
      } else {
        selectedUids.add(uid);
        row.classList.add('rd-row-selected');
      }
    } else if (selectedUids.has(uid)) {
      // A plain click on an already-selected row clears the whole
      // selection (Escape does the same).
      clearSelection(false);
    } else {
      clearSelection(false);
      selectedUids.add(uid);
      row.classList.add('rd-row-selected');
    }
    announceSelection();
  });

  document.addEventListener('keydown', function (ev) {
    if (ev.key !== 'Escape' || !selectedUids.size) return;
    clearSelection();
  });
})();

/* Space Grotesk (OFL 1.1, https://fonts.google.com/specimen/Space+Grotesk)
 * Variable latin subset, embedded as a data URI so the app stays fully
 * offline-capable under both native Shiny and the shinylive export.
 */
@font-face {
  font-family: 'Space Grotesk';
  font-style: normal;
  font-weight: 300 700;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}

// Fullscreen toggle for the plot area.  The button lives inside the
// server-rendered plot toolbar (re-created on every plot_area render), so
// the wiring is delegated and the on/off state is a class on <html> --
// both survive re-renders, and app.css derives the overlay layout, the
// hidden chrome (hints, tabs, memory note) and the button's icon from
// that class alone.
//
// Entering also requests native browser fullscreen (hiding the URL bar
// and tabs).  When that is unavailable -- e.g. the shinylive viewer
// iframe lacks allowfullscreen -- the request fails silently and the
// CSS overlay still fills the browser window.
(function () {
  'use strict';

  function fsActive() {
    return document.documentElement.classList.contains('rd-fullscreen');
  }

  /* Toggle the state class and tell the bridge, which relays it into the
   * report iframe so the figure can scale to the viewport. */
  function applyState(on) {
    document.documentElement.classList.toggle('rd-fullscreen', on);
    document.dispatchEvent(
      new CustomEvent('rd-fs-change', { detail: { on: on } })
    );
  }

  /* The drill-down tab strip is hidden in fullscreen, so make sure the
   * Plot pane (always the first tab) is the visible one before entering. */
  function activatePlotTab() {
    var link = document.querySelector('.rd-plot-area .nav-tabs .nav-link');
    if (link && !link.classList.contains('active')) link.click();
  }

  function setFullscreen(on) {
    applyState(on);
    if (on) {
      activatePlotTab();
      if (!document.fullscreenElement && document.documentElement.requestFullscreen) {
        document.documentElement.requestFullscreen().catch(function () {});
      }
    } else if (document.fullscreenElement && document.exitFullscreen) {
      document.exitFullscreen().catch(function () {});
    }
  }

  document.addEventListener('click', function (ev) {
    var btn = ev.target.closest && ev.target.closest('.rd-fs-btn');
    if (!btn) return;
    setFullscreen(!fsActive());
  });

  // Escape with something selected clears the selection instead of
  // exiting; only an Escape with nothing selected leaves fullscreen.
  // The report announces its selection state ('rd-selection-state') and
  // the annotations table announces its rows ('rd-ft-selection').
  var reportHasSelection = false;
  var tableSelectionCount = 0;

  function anySelection() {
    return reportHasSelection || tableSelectionCount > 0;
  }

  function clearReportSelection() {
    var frame = document.querySelector('iframe.rd-report-frame');
    if (frame && frame.contentWindow) {
      frame.contentWindow.postMessage({ type: 'rd-clear-selection' }, '*');
    }
  }

  window.addEventListener('message', function (ev) {
    var msg = ev && ev.data;
    if (!msg) return;
    if (msg.type === 'rd-selection-state') {
      reportHasSelection = !!msg.any;
    } else if (msg.type === 'rd-report-ready') {
      // A fresh iframe starts with nothing selected.
      reportHasSelection = false;
    } else if (msg.type === 'rd-esc' && fsActive()) {
      // Escape inside the report with nothing left to clear.
      setFullscreen(false);
    }
  });

  document.addEventListener('rd-ft-selection', function (ev) {
    var features = ev && ev.detail && ev.detail.features;
    tableSelectionCount = Array.isArray(features) ? features.length : 0;
  });

  // Native fullscreen exits on its own Escape (or browser UI).  If that
  // Escape had a selection to clear, keep the overlay in place (the
  // browser's exit itself cannot be prevented) so the next Escape is the
  // one that actually leaves fullscreen; otherwise drop the overlay so
  // the two states never diverge.
  document.addEventListener('fullscreenchange', function () {
    if (document.fullscreenElement || !fsActive()) return;
    if (anySelection()) {
      clearReportSelection();
    } else {
      applyState(false);
    }
  });

  // Capture phase so this sees the selection state before the table's own
  // Escape handler clears it.  Only reaches this document when focus is
  // outside the sandboxed report iframe; Escape inside the iframe is
  // handled by the report itself (clearing first, then 'rd-esc').
  document.addEventListener(
    'keydown',
    function (ev) {
      if (ev.key !== 'Escape' || !fsActive()) return;
      if (anySelection()) {
        clearReportSelection();
        // The annotations table clears its own rows on this same keydown.
      } else {
        setFullscreen(false);
      }
    },
    true
  );
})();

// Keep the sidebar's scroll position when a file is chosen in it.
//
// Picking a GFF sends the sidebar back to the top, losing the user's place
// right after an action whose result (the feature-type list) is further
// down the panel.
//
// Instrumenting the scroll container shows the jump has already happened by
// the time the input's `change` event fires — it comes out of the file
// picker interaction itself, not out of the dependent outputs re-rendering
// afterwards.  So the position has to be captured when the picker is
// opened, and re-asserted once the file comes back.
//
// The hold spans the upload and the re-renders it triggers, because the
// panel keeps growing as those outputs fill in and a single restore would
// be clamped against a height that is still settling.  Any real scroll
// gesture cancels it, so this can never fight the user for the scrollbar.

(function () {
  'use strict';

  // Long enough to cover the upload plus the dependent re-renders; short
  // enough that a stuck hold would be imperceptible.
  var HOLD_MS = 2000;

  /* Nearest scrollable ancestor, or null.  The scroller is bslib's
   * <aside class="sidebar"> on desktop but the inner .sidebar-content once
   * the layout collapses, so find it rather than hard-coding either. */
  function scrollerFor(el) {
    var node = el;
    while (node && node !== document.documentElement) {
      if (node.scrollHeight > node.clientHeight + 2) {
        var overflowY = window.getComputedStyle(node).overflowY;
        if (overflowY === 'auto' || overflowY === 'scroll') return node;
      }
      node = node.parentElement;
    }
    return null;
  }

  function sidebarFileInput(el) {
    if (!el || el.type !== 'file' || !el.closest) return null;
    return el.closest('.sidebar') ? el : null;
  }

  var mark = null; // {el, top} captured when the picker was opened
  var hold = null; // {el, top, until} active restore

  function release() {
    hold = null;
  }

  // Any genuine scroll gesture wins; the hold exists only to undo the
  // programmatic jump, never to pin the panel against the user.
  ['wheel', 'touchmove', 'keydown'].forEach(function (name) {
    document.addEventListener(name, release, { passive: true, capture: true });
  });

  function tick() {
    if (!hold) return;
    if (Date.now() > hold.until) {
      hold = null;
      return;
    }
    var el = hold.el;
    var want = Math.min(hold.top, el.scrollHeight - el.clientHeight);
    if (el.scrollTop !== want) el.scrollTop = want;
    requestAnimationFrame(tick);
  }

  // Opening the picker is the last moment the user's position is still on
  // screen, so record it here rather than on `change`.
  document.addEventListener(
    'pointerdown',
    function (ev) {
      var input = sidebarFileInput(ev.target);
      if (!input) return;
      var scroller = scrollerFor(input);
      if (scroller && scroller.scrollTop > 0) {
        mark = { el: scroller, top: scroller.scrollTop };
      }
    },
    true
  );

  document.addEventListener(
    'click',
    function (ev) {
      var input = sidebarFileInput(ev.target);
      if (!input) return;
      var scroller = scrollerFor(input);
      if (scroller && scroller.scrollTop > 0) {
        mark = { el: scroller, top: scroller.scrollTop };
      }
    },
    true
  );

  document.addEventListener(
    'change',
    function (ev) {
      var input = sidebarFileInput(ev.target);
      if (!input) return;
      var scroller = scrollerFor(input);
      if (!scroller) return;
      // Prefer the pre-picker position; fall back to the current one when
      // the picker never moved it (nothing to undo, but the re-renders
      // below can still clamp it).
      var top = mark && mark.el === scroller ? mark.top : scroller.scrollTop;
      mark = null;
      if (top <= 0) return;
      hold = { el: scroller, top: top, until: Date.now() + HOLD_MS };
      requestAnimationFrame(tick);
    },
    true
  );
})();

// Mirror ui.Progress messages into the header's task-status slot.
//
// The server keeps using ui.Progress unchanged -- its messages flush
// synchronously mid-computation, which a reactive output cannot do -- but
// the popup card it draws (a .shiny-progress-notification inside the
// notification panel) duplicates the busy pill, so app.css hides it and
// this observer copies its text into #rd-task-status at the right end of
// the header bar instead.  Ordinary ui.notification_show toasts have no
// .shiny-progress-notification node and are untouched.

(function () {
  'use strict';

  var scheduled = false;

  function sync() {
    scheduled = false;
    var slot = document.getElementById('rd-task-status');
    if (!slot) return;
    var cards = document.querySelectorAll('.shiny-progress-notification');
    if (!cards.length) {
      if (slot.textContent) slot.textContent = '';
      return;
    }
    // Several progress bars can stack (nested renders); the newest one is
    // the task actually running now.
    var card = cards[cards.length - 1];
    var message = card.querySelector('.progress-message');
    var detail = card.querySelector('.progress-detail');
    var text = (
      (message ? message.textContent : '') +
      ' ' +
      (detail ? detail.textContent : '')
    ).trim();
    // The placeholder text before the first real .set() call.
    if (text === 'message') text = '';
    if (slot.textContent !== text) slot.textContent = text;
  }

  function schedule() {
    if (scheduled) return;
    scheduled = true;
    window.requestAnimationFrame(sync);
  }

  new MutationObserver(schedule).observe(document.documentElement, {
    childList: true,
    subtree: true,
    characterData: true,
  });
})();
